#include "../src/microvm/gui/DesktopViewer.h"
#include <Windows.h>
#include <vector>
#include <iostream>
#include <stdexcept>
namespace d=guardian::desktop;static unsigned checks=0;static void Check(bool b){++checks;if(!b)throw std::runtime_error("Viewer contract failed at "+std::to_string(checks));}
int main(){try{av::microvm::desktop_session::Viewer viewer(false);const auto h=FindWindowW(L"Aegis.MiniNT.DesktopViewer.14.7",L"MiniNT - desktop convidado");DWORD pid=0;Check(h&&GetWindowThreadProcessId(h,&pid)==GetCurrentThreadId()&&pid==GetCurrentProcessId());while(viewer.Poll().type!=d::InputType::None){}
PostMessageW(h,WM_KEYDOWN,'A',1|(30<<16));PostMessageW(h,WM_KEYUP,'A',LPARAM(1ull|(30ull<<16)|(1ull<<30)|(1ull<<31)));PostMessageW(h,WM_CHAR,0xE9,1);PostMessageW(h,WM_MOUSEMOVE,0,MAKELPARAM(200,150));PostMessageW(h,WM_LBUTTONDOWN,MK_LBUTTON,MAKELPARAM(200,150));PostMessageW(h,WM_LBUTTONUP,0,MAKELPARAM(200,150));std::vector<d::Input> events;for(unsigned n=0;n<12;++n){const auto e=viewer.Poll();if(e.type==d::InputType::None)break;Check(d::ValidInput(e));if(e.type!=d::InputType::Blur)events.push_back(e);}if(events.size()!=6){for(const auto& e:events)std::cerr<<"event "<<uint32_t(e.type)<<" key "<<e.key<<" buttons "<<e.buttons<<'\n';}Check(events.size()==6);Check(events[0].type==d::InputType::KeyDown&&events[0].key=='A'&&events[0].scan==30);Check(events[1].type==d::InputType::KeyUp);Check(events[2].type==d::InputType::Text&&events[2].key==0xE9);Check(events[3].type==d::InputType::Move);Check(events[4].type==d::InputType::Button&&events[4].buttons==1);Check(events[5].buttons==0);std::vector<uint32_t> pixels(d::PixelCount,0xFF123456);d::Frame f;viewer.Display(f,pixels.data());PostMessageW(h,WM_KILLFOCUS,0,0);Check(viewer.Poll().type==d::InputType::Blur);PostMessageW(h,WM_CLOSE,0,0);Check(viewer.Poll().type==d::InputType::Close&&IsWindow(h));std::cout<<"Single desktop viewer physical keys, independent text, mouse, blur, frame and close PASS\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
